        // EXERCISE 11: Echo-Shadow
        // Focus: Listening and mimicking complete sentences with target grammar (Reported Speech, Tags, Embedded Qs, Phrasal Verbs).
        11: [
            {waveform_data:[2,5,8,12,10,6,3,5,2],transcript_text:"Could you tell me where the problem is?"},
            {waveform_data:[3,6,9,11,8,5,4,7,3],transcript_text:"I wonder if she passed the test."},
            {waveform_data:[4,7,10,12,9,6,3,5,4],transcript_text:"He said that he had failed the exam."},
            {waveform_data:[2,4,6,8,10,8,6,4,2],transcript_text:"She told me that she was struggling."},
            {waveform_data:[3,5,7,9,11,9,7,5,3],transcript_text:"We have the strength to win, don't we?"},
            {waveform_data:[1,3,5,7,9,11,8,4,2],transcript_text:"You won't give up now, will you?"},
            {waveform_data:[2,6,10,8,6,4,2,5,3],transcript_text:"Let's carry out the plan today, shall we?"},
            {waveform_data:[4,8,12,10,8,6,4,2,5],transcript_text:"I am very resilient, aren't I?"},
            {waveform_data:[3,7,11,9,7,5,3,6,4],transcript_text:"They had to call off the meeting."},
            {waveform_data:[5,9,11,8,5,3,6,4,2],transcript_text:"The tragedy called for immediate support."},
            {waveform_data:[2,4,8,12,10,7,4,2,5],transcript_text:"She called up her friends for advice."},
            {waveform_data:[3,5,9,11,8,6,3,5,2],transcript_text:"I will call back in a few minutes."},
            {waveform_data:[4,6,10,12,9,5,3,6,4],transcript_text:"The school called in an expert."},
            {waveform_data:[2,5,7,11,9,6,4,2,5],transcript_text:"He called out the bad behavior publicly."},
            {waveform_data:[3,6,8,12,10,7,5,3,6],transcript_text:"We must carry on despite the adversity."},
            {waveform_data:[5,8,11,9,6,4,2,5,3],transcript_text:"They will carry out the project successfully."},
            {waveform_data:[2,4,7,10,12,8,5,3,6],transcript_text:"The debt will carry over to next month."},
            {waveform_data:[3,5,8,11,9,6,4,2,5],transcript_text:"Don't get carried away by the victory."},
            {waveform_data:[4,7,9,12,10,7,4,2,5],transcript_text:"This song carries me back to my childhood."},
            {waveform_data:[2,5,8,10,12,9,6,3,5],transcript_text:"She carried off the performance perfectly."},
            {waveform_data:[3,5,7,10,8,6,4,3,2],transcript_text:"He said that he would carry on."},
            {waveform_data:[2,6,9,11,10,7,5,3,4],transcript_text:"Celine said that she could cope with it."},
            {waveform_data:[4,5,8,12,9,6,4,5,3],transcript_text:"The teacher said that we had to focus."},
            {waveform_data:[2,4,7,9,11,8,5,4,2],transcript_text:"Do you know where the counselor is?"},
            {waveform_data:[3,6,8,10,12,9,6,4,3],transcript_text:"Could you tell me why he is crying?"},
            {waveform_data:[2,4,6,8,11,10,7,5,3],transcript_text:"Persistence is key, isn't it?"},
            {waveform_data:[3,7,10,9,7,5,4,6,3],transcript_text:"He overcame the setback, didn't he?"},
            {waveform_data:[4,8,11,10,8,5,3,4,2],transcript_text:"You can achieve your goals, can't you?"},
            {waveform_data:[3,6,10,11,8,6,4,5,3],transcript_text:"She said that she was busy then."},
            {waveform_data:[5,8,12,10,7,5,3,6,4],transcript_text:"He said he was struggling that day."},
            {waveform_data:[2,5,9,11,10,8,5,4,3],transcript_text:"They said they had failed the day before."},
            {waveform_data:[3,6,10,12,9,7,5,4,2],transcript_text:"He told me he was waiting there."},
            {waveform_data:[4,7,11,10,8,5,3,4,2],transcript_text:"I don't know if I can overcome this."},
            {waveform_data:[2,4,8,12,9,6,4,5,3],transcript_text:"I struggle with math sometimes."},
            {waveform_data:[3,5,9,11,10,8,6,4,3],transcript_text:"It is important to embrace new challenges."},
            {waveform_data:[5,7,10,12,9,6,4,3,2],transcript_text:"I feel overwhelmed by all the news."},
            {waveform_data:[2,6,9,11,10,8,5,4,3],transcript_text:"Time is precious, we shouldn't waste it."},
            {waveform_data:[3,5,8,12,10,7,5,3,2],transcript_text:"I will call around to find the book."},
            {waveform_data:[4,8,10,12,9,6,4,3,5],transcript_text:"The teacher called on me to answer."},
            {waveform_data:[2,4,7,10,11,8,6,4,3],transcript_text:"His faith carried him through the dark times."}
        ],

